'use client'
import { cn, normalizeTone, useSignals } from '@cascivo/core'
import type { ToneInput } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import type { HTMLAttributes } from 'react'
import styles from './tag.module.css'

/** Canonical tone → the value Tag's stylesheet keys on. */
const TONE_CLASS: Record<string, string> = {
  neutral: 'default',
  info: 'info',
  success: 'success',
  warning: 'warning',
  danger: 'error',
}

export interface TagProps extends HTMLAttributes<HTMLSpanElement> {
  /**
   * Severity tone. Accepts the catalog-wide `Tone` vocabulary (`neutral | info | success |
   * warning | danger`) plus Tag's historical spellings (`default` → neutral,
   * `error`/`destructive` → danger).
   *
   * @defaultValue `default`
   * @see the component manifest
   */
  variant?: ToneInput
  size?: 'sm' | 'md'
  onDismiss?: () => void
  /**
   * Accessible label for the dismiss button.
   *
   * @defaultValue `Remove`
   * @see the component manifest
   */
  dismissLabel?: string
}

export function Tag({
  variant = 'default',
  size = 'md',
  onDismiss,
  dismissLabel,
  className,
  children,
  ...props
}: TagProps) {
  useSignals()
  const resolvedDismissLabel = dismissLabel ?? t(builtin.tag.dismiss)
  return (
    <span
      data-variant={TONE_CLASS[normalizeTone(variant)] ?? variant}
      data-size={size}
      className={cn(styles['tag'], className)}
      {...props}
    >
      {children}
      {onDismiss && (
        <button
          type="button"
          className={styles['dismiss']}
          aria-label={resolvedDismissLabel}
          onClick={onDismiss}
        >
          ✕
        </button>
      )}
    </span>
  )
}

@layer cascivo.component {
  .tag {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    font-family: var(--cascivo-font-sans);
    font-weight: var(--cascivo-font-medium);
    border-radius: var(--cascivo-radius-badge);
    /* Transparent by default so each tone can opt into a visible edge without shifting
       layout — same base as Badge. Without a border-style, a tone's `border-color` is inert. */
    border: 1px solid transparent;
    white-space: nowrap;

    &[data-size='sm'] {
      padding-inline: var(--cascivo-space-2);
      padding-block: var(--cascivo-space-1);
      font-size: var(--cascivo-text-xs);
      line-height: 1;
    }

    &[data-size='md'] {
      padding-inline: var(--cascivo-space-3);
      padding-block: var(--cascivo-space-1);
      font-size: var(--cascivo-text-xs);
      line-height: var(--cascivo-leading-normal);
    }

    &[data-variant='default'] {
      background-color: var(--cascivo-color-bg-subtle);
      color: var(--cascivo-color-text-subtle);
      /* Subtle bg on a subtle surface is nearly invisible in dark themes; the border is
         what keeps a neutral tag reading as a chip rather than as loose text. */
      border-color: var(--cascivo-color-border);
    }

    &[data-variant='info'] {
      background-color: var(--cascivo-color-info-subtle);
      color: var(--cascivo-color-info-foreground);
    }

    &[data-variant='success'] {
      background-color: var(--cascivo-color-success-subtle);
      color: var(--cascivo-color-success-foreground);
    }

    &[data-variant='warning'] {
      background-color: var(--cascivo-color-warning-subtle);
      color: var(--cascivo-color-warning-foreground);
    }

    &[data-variant='error'] {
      background-color: var(--cascivo-color-destructive-subtle);
      color: var(--cascivo-color-destructive-foreground);
    }
  }

  .dismiss {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    margin-inline-end: calc(-1 * var(--cascivo-space-1));
    border: none;
    background: transparent;
    color: currentColor;
    font-size: inherit;
    line-height: 1;
    cursor: pointer;
    border-radius: var(--cascivo-radius-full);
    opacity: 0.7;
    transition: opacity var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      opacity: 1;
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
      opacity: 1;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Tag',
  description: 'Compact chip for labeling, categorizing, or filtering content',
  category: 'display',
  // The chip and its label render; only the optional dismiss button needs JS.
  clientJs: 'enhancement',
  states: [],
  variants: ['default', 'info', 'success', 'warning', 'error'],
  sizes: ['sm', 'md'],
  props: [
    {
      name: 'variant',
      description:
        "Severity tone. Accepts the catalog-wide `Tone` vocabulary (`neutral | info | success | warning | danger`) plus Tag's historical spellings (`default` → neutral, `error`/`destructive` → danger).",
      type: "'default' | 'info' | 'success' | 'warning' | 'error'",
      required: false,
      default: 'default',
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md'",
      required: false,
      default: 'md',
    },
    {
      name: 'onDismiss',
      type: '() => void',
      required: false,
      description: 'When provided, renders a trailing remove button inside the chip',
    },
    {
      name: 'dismissLabel',
      description: 'Accessible label for the dismiss button.',
      type: 'string',
      required: false,
      default: 'Remove',
    },
  ],
  tokens: [
    '--cascivo-color-bg-subtle',
    '--cascivo-color-text-subtle',
    '--cascivo-color-info',
    '--cascivo-color-info-subtle',
    '--cascivo-color-success',
    '--cascivo-color-success-subtle',
    '--cascivo-color-warning',
    '--cascivo-color-warning-subtle',
    '--cascivo-color-destructive',
    '--cascivo-color-destructive-subtle',
    '--cascivo-radius-badge',
    '--cascivo-focus-ring',
  ],
  accessibility: { role: 'none', wcag: '2.2-AA', keyboard: ['Enter', 'Space'] },
  examples: [
    { title: 'Default', code: '<Tag>Design</Tag>' },
    { title: 'Success', code: '<Tag variant="success">Approved</Tag>' },
    {
      title: 'Dismissible',
      code: '<Tag onDismiss={() => removeFilter()}>Filter: Active</Tag>',
      description: 'Renders a trailing remove button labeled by dismissLabel',
    },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['chip', 'label', 'filter', 'category'],
  intent: {
    whenToUse: [
      'Labeling, categorizing, or filtering content with a compact chip',
      'Representing a removable selection or active filter (onDismiss)',
      'Showing a set of keywords or attributes on an item',
    ],
    whenNotToUse: [
      'A static, non-interactive status label — use Badge',
      'A live system state with a dot — use Status',
    ],
    antiPatterns: [
      {
        bad: 'Using Badge with a custom close button to make it removable',
        good: '<Tag onDismiss={remove}> which renders a proper labeled remove button',
        why: 'Tag provides accessible dismiss semantics; bolting interactivity onto Badge skips that',
      },
    ],
    related: [
      {
        name: 'Badge',
        relationship: 'alternative',
        reason: 'Badge is the static, non-interactive counterpart',
      },
      {
        name: 'TagsInput',
        relationship: 'contained-by',
        reason: 'TagsInput renders Tags for each entered value',
      },
    ],
    a11yRationale:
      'When dismissible, the remove control is a real button with a label (dismissLabel) so keyboard users can remove it via Enter/Space; color variants are reinforced by text, not hue alone',
    content: {
      tone: 'Short noun labels',
      notes: 'dismissLabel should name what is removed',
    },
    flexibility: [
      {
        area: 'variant and dismissibility',
        level: 'flexible',
        note: 'onDismiss is optional; variant matches semantic meaning',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Variant colors must resolve to --cascivo-color-*-subtle tokens',
      },
    ],
  },
}
